def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        return (major, minor, patch, pre)

    def pre_key(pre):
        if pre is None:
            return None
        ids = pre.split('.')
        key = []
        for ident in ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_pre(a, b):
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        ka, kb = pre_key(a), pre_key(b)
        for x, y in zip(ka, kb):
            if x < y:
                return -1
            if x > y:
                return 1
        if len(ka) < len(kb):
            return -1
        if len(ka) > len(kb):
            return 1
        return 0

    import functools

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        if p1[:3] != p2[:3]:
            return -1 if p1[:3] < p2[:3] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

